window.AUTH=window.AUTH||{};window.AUTH["13-1402"]={"d":"13-1402","id":"2014/13-1402","n":"Kerry v. Din","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the petitioners","date":"2014-11-26","url":"https://www.justice.gov/osg/media/252231/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/kerry-v-din-0","n":138},{"k":"reply","label":"Reply brief for the petitioners","date":"2015-02-11","url":"https://www.justice.gov/osg/media/405676/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/kerry-v-din-1","n":54}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Abourezk v. Reagan","cite":"785 F.2d 1043","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/785/1043/","by":{"0":"51"}},{"t":"case","label":"American Acad. of Religion v. Napolitano","cite":"573 F.3d 115","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/573/115/","by":{"0":"40"}},{"t":"case","label":"Bangura v. Hansen","cite":"434 F.3d 487","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/434/487/","sum":"Stating that the “Constitution does not recognize the right of a citizen spouse to have his or her alien spouse remain in the country” and that “[a] denial of an immediate relative visa does not infringe upon their right to marry”.","sumSrc":"brief:0","by":{"0":"26","1":"10"}},{"t":"case","label":"Board of Regents of State Colls. v. Roth","cite":"408 U.S. 564","y":1972,"id":"1971/71-162","sc":1,"sum":"The court held 5-3 that Roth had no protected interest in continued employment, as he had completed his contracted term, and therefore was no Fourteenth Amendment protection.","sumSrc":"Oyez","by":{"0":"21, 22","1":"12"}},{"t":"case","label":"Brownell v. Tom We Shung","cite":"352 U.S. 180","y":1956,"id":"1956/43","sc":1,"sum":"Under § 10 of the Administrative Procedure Act, an alien whose exclusion has been ordered administratively under the Immigration and Nationality Act of 1952, and who neither claims citizenship nor holds a certificate of identity issued under § 360 (b) of that Act, may obtain judicial review of such order by an action in a federal district court for a declaratory judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Burrafato v. United States Dep’t of State","cite":"523 F.2d 554","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/523/554/","sum":"Ruling that “the claim that denial of [the alien’s] visa application violated the constitutional rights of [the U.S.-citizen spouse]” was “foreclosed” and that “the failure of the Department of State * * * to specify the reasons for denial of [the alien’s] visa application” did not “implicate[]” any “constitutional rights of American citizens over which a federal court would have jurisdiction”.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Bustamante v. Mukasey","cite":"531 F.3d 1059","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/531/1059/","ar":2,"by":{"0":"10, 11, 20, 23"}},{"t":"case","label":"CIA v. Sims","cite":"471 U.S. 159","y":1985,"id":"1984/83-1075","sc":1,"sum":"Between 1953 and 1966, the Central Intelligence Agency (CIA) financed a research project, code-named MKULTRA, that was established to counter Soviet and Chinese advances in brainwashing and interrogation techniques. Subprojects were contracted out to various universities, research foundations, and similar institutions. In 1977, respondents in No. 83-1075 (hereafter respondents) filed a request with the CIA under the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 49"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"133 S. Ct. 1138","y":2013,"id":"2012/11-1025","sc":1,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Cleveland Bd. of Educ. v. LaFleur","cite":"414 U.S. 632","y":1974,"id":"1973/72-777","sc":1,"sum":"The Court held that the school boards' regulations requiring pregnant teachers to stop working after the fifth month of their pregnancies violated the Fourteenth Amendment's due process clause.","sumSrc":"Oyez","by":{"0":"22, 23"}},{"t":"case","label":"Cohens v. Virginia","cite":"19 U.S. 264","y":1821,"id":"1789-1850/19us264","sc":1,"sum":"The Court decided it had jurisdiction over all cases involving Constitutional questions, including state supreme court decisions.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Department of the Navy v. Egan","cite":"484 U.S. 518","y":1988,"id":"1987/86-1552","sc":1,"sum":"In an appeal pursuant to § 7513, the Board does not have authority to review the substance of an underlying security-clearance determination in the course of reviewing an adverse action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42, 44","1":"14"}},{"t":"case","label":"Fasano v. United States","cite":"230 Fed. Appx. 239","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./230/239/","by":{"0":"26"}},{"t":"case","label":"Fiallo v. Bell","cite":"430 U.S. 787","y":1977,"id":"1976/75-6297","sc":1,"ar":3,"sum":"Sections 101 (b) (1) (D) and 101 (b) (2) of the Immigration and Nationality Act of 1952, which have the effect of excluding the relationship between an illegitimate child and his natural father (as opposed to his natural mother) from the special preference immigration status accorded by the Act to the \"child\" or \"parent\" of a United States citizen or lawful permanent resident, held not to be unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 20, 25, 27, 40","1":"6, 8, 10, 11"}},{"t":"case","label":"Galvan v. Press","cite":"347 U.S. 522","y":1954,"id":"scdb/1953-075","sc":1,"sum":"1. Section 22 of the Internal Security Act of 1950, providing for the deportation of any alien who has been a member of the Communist Party at any time after entry, is constitutional-as here applied to a resident alien shown to have been willingly a member of the Communist Party from 1944 to 1946 although not shown to have been aware of its advocacy of violent overthrow of the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"9"}},{"t":"case","label":"Garcia v. Boldin","cite":"691 F.2d 1172","y":1982,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/691/1172/","by":{"0":"26"}},{"t":"case","label":"Griswold v. Connecticut","cite":"381 U.S. 479","y":1965,"id":"1964/496","sc":1,"ar":1,"sum":"The Court found that a Connecticut law requiring counseling and medical treatment violated a woman's right to privacy guaranteed by the First, Third, Fourth, and Ninth Amendments.","sumSrc":"Oyez","by":{"0":"22, 23","1":"7"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"sum":"Explaining that “any policy toward aliens is vitally and intricately interwoven with contemporaneous policies in regard to the conduct of foreign relations, the war power, and the maintenance of a republican form of government”.","sumSrc":"brief:0","by":{"0":"35, 36, 42","1":"8"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"42, 50, 53","1":"19, 21"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"sum":"The Court noted that withholding of deportation is mandatory if an alien establishes that it is more likely than not that he or she will suffer political persecution if deported.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Ingraham v. Wright","cite":"430 U.S. 651","y":1977,"id":"1976/75-6527","sc":1,"sum":"The Court held that the Eighth Amendment does not prevent corporal punishment in public schools. While acknowledging the general abandonment of corporal punishment as a means of punishing criminals, Justice Powell looked to the common law history of similar punishment in schools and discerned no trend towards its elimination.","sumSrc":"Oyez","by":{"0":"21, 22, 26, 28","1":"15"}},{"t":"case","label":"Jifry v. FAA","cite":"370 F.3d 1174","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/370/1174/","by":{"0":"51"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"passim","1":"passim"}},{"t":"case","label":"Landon v. Plasencia","cite":"459 U.S. 21","y":1982,"id":"1982/81-129","sc":1,"sum":"Section 235 of the Immigration and Nationality Act of 1952 (Act) permits the Immigration and Naturalization Service (INS) to examine \"all aliens\" who seek \"admission or readmission to\" the United States and empowers immigration officers to take evidence concerning the privilege of any persons suspected of being an alien \"to enter, reenter, pass through, or reside\" in the United States, and to detain for further …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Lehr v. Robertson","cite":"463 U.S. 248","y":1983,"id":"1982/81-1756","sc":1,"sum":"The Supreme Court held that due process and equal protection were not violated because Lehr never had a significant personal or financial relationship with Jessica M. Justice Byron R. White dissented, arguing that the state cannot deny notice of adoption proceedings to a biological father when the state knows his whereabouts and interest in the child.","sumSrc":"Oyez","by":{"0":"22, 24","1":"8"}},{"t":"case","label":"Loving v. Virginia","cite":"388 U.S. 1","y":1967,"id":"1966/395","sc":1,"sum":"The Court held that the Fourteenth Amendment prohibits governments from discriminating against individuals on the basis of race.","sumSrc":"Oyez","by":{"0":"22","1":"7"}},{"t":"case","label":"Meachum v. Fano","cite":"427 U.S. 215","y":1976,"id":"1975/75-252","sc":1,"sum":"The Due Process Clause of the Fourteenth Amendment held not to entitle a duly convicted state prisoner to a factfinding hearing when he is transferred to a prison the conditions of which are substantially less favorable to him, absent a state law or practice conditioning such transfers on proof of serious misconduct or the occurrence of other specified events. Such a transfer does not infringe or implicate a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Medina-Hincapie v. Department of State","cite":"700 F.2d 737","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/700/737/","by":{"0":"41"}},{"t":"case","label":"Meyer v. Nebraska","cite":"262 U.S. 390","y":1923,"id":"1900-1940/262us390","sc":1,"ar":1,"sum":"A case in which the Court struck down under the Fourteenth Amendment a Nebraska law prohibiting teachers from instructing grade school children any language other than English.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Moore v. City of E. Cleveland","cite":"431 U.S. 494","y":1977,"id":"1976/75-6289","sc":1,"sum":"The four justices in the plurality held that the ordinance violated Moore's rights as it constituted \"intrusive regulation of the family\" without accruing some tangible state interest. Justice Stevens joined in the judgment and argued that the ordinance was invalid because, by regulating who could live with Moore, it constituted a taking of property without just compensation.","sumSrc":"Oyez","by":{"0":"22, 27, 28","1":"8"}},{"t":"case","label":"Morales-Izquierdo v. Department of Homeland Sec.","cite":"600 F.3d 1076","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/600/1076/","by":{"0":"28, 31"}},{"t":"case","label":"Nishimura Ekiu v. United States","cite":"142 U.S. 651","y":1892,"id":"scdb/1891-092","sc":1,"sum":"The act of March 3, 1891, c. 551, forbidding certain classes of alien immigrants to land in the United States, is constitutional and valid.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"O’Bannon v. Town Court Nursing Ctr.","cite":"447 U.S. 773","y":1980,"id":"1979/78-1318","sc":1,"sum":"The patients have no interest in receiving benefits for care in a particular facility that entitles them, as a matter of constitutional law, to a hearing before HEW and DPW can decertify that facility. Whatever legal rights the patients may have against the nursing home for failing to maintain its status as a qualified nursing home, the enforcement by HEW and DPW of their valid regulations did not directly affect …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 29, 30, 31, 32","1":"3, 4, 5, 12"}},{"t":"case","label":"Oceanic Steam Navigation Co. v. Stranahan","cite":"214 U.S. 320","y":1909,"id":"scdb/1908-176","sc":1,"sum":"Money paid to the collector of a port under protest, and on the certainty that if not paid clearance to vessels necessarily sailing on definite schedule would be refused, to the great damage of the owner, is paid involuntarily,'and can, if unlawfully exacted, be recovered;","sumSrc":"Headnote (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Oforji v. Ashcroft","cite":"354 F.3d 609","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/354/609/","by":{"0":"26"}},{"t":"case","label":"Payne-Barahona v. Gonzáles","cite":"474 F.3d 1","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/474/1/","by":{"0":"27, 32"}},{"t":"case","label":"Reno v. Flores","cite":"507 U.S. 292","y":1993,"id":"1992/91-905","sc":1,"sum":"Respondents are a class of alien juveniles arrested by the Immigration and Naturalization Service (INS) on suspicion of being deportable, and then detained pending deportation hearings pursuant to a regulation, promulgated in 1988 and codified at 8 CFR §242.24, which provides for the release of detained minors only to their parents, close relatives, or legal guardians, except in unusual and compelling circumstances. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 22, 24, 28","1":"8"}},{"t":"case","label":"Rostker v. Goldberg","cite":"453 U.S. 57","y":1981,"id":"1980/80-251","sc":1,"sum":"In a 6-to-3 decision, the Court held that Congress's decision to exempt women from registration \"was not the 'accidental by-product of a traditional way of thinking about females'\" and did not violate the Due Process Clause. The Court found that men and women, because of combat restrictions on women, were not \"similarly situated\" for the purposes of draft registration.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Saavedra Bruno v. Albright","cite":"197 F.3d 1153","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/197/1153/","by":{"0":"7, 20, 34, 40","1":"14"}},{"t":"case","label":"Scialabba v. Cuellar De Osorio","cite":"134 S. Ct. 2191","y":2014,"id":"2013/12-930","sc":1,"sum":"The Court held that the Immigration and Nationality Act does not allow children who have submitted an application for a visa to keep their original application date if they \"aged out\" before it was processed.","sumSrc":"Oyez","by":{"0":"3, 4, 18"}},{"t":"case","label":"Shaughnessy v. United States ex rel. Mezei","cite":"345 U.S. 206","y":1953,"id":"scdb/1952-067","sc":1,"sum":"The Attorney General's continued exclusion of the alien without a hearing does not amount to an unlpvful detention, and courts may not temporarily admit him to the iJnited States pending arrangements for his departure abroad.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 35, 42, 43, 45"}},{"t":"case","label":"Silverman v. Rogers","cite":"437 F.2d 102","y":1970,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/437/102/","by":{"0":"23, 24"}},{"t":"case","label":"Swartz v. Rogers","cite":"254 F.2d 338","y":1958,"url":"https://www.courtlistener.com/c/F.2d/254/338/","by":{"0":"23, 24, 26"}},{"t":"case","label":"Town of Castle Rock v. Gonzales","cite":"545 U.S. 748","y":2005,"id":"2004/04-278","sc":1,"sum":"The Court ruled that Gonzales had no constitutionally-protected property interest in the enforcement of the restraining order, and therefore could not claim that the police had violated her right to due process.","sumSrc":"Oyez","by":{"0":"30","1":"4"}},{"t":"case","label":"United States v. Curtiss-Wright Exp. Corp.","cite":"299 U.S. 304","y":1936,"id":"1900-1940/299us304","sc":1,"sum":"The Court held that the President has greater legislative power in international affairs than would be allowed in domestic ones.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"United States ex rel. Knauff v. Shaughnessy","cite":"338 U.S. 537","y":1950,"id":"scdb/1949-033","sc":1,"ar":3,"sum":"This action was authorized by the Act of June 21, 1941, 22 U. S. C. § 223, and the proclamations and regulations issued thereunder, notwithstanding the War Brides Act of December 28, 1945, 8 U. S. C. § 232 et seq.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"14, 15, 18, 19"}},{"t":"case","label":"United States ex rel. London v. Phelps","cite":"22 F.2d 288","y":1927,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/22/288/","by":{"0":"34"}},{"t":"case","label":"United States ex rel. Ulrich v. Kellogg","cite":"30 F.2d 984","y":1929,"url":"https://www.courtlistener.com/c/F.2d/30/984/","by":{"0":"34"}},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"ar":1,"sum":"The Court decided that a law banning physician-assisted suicide does not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"21, 22","1":"9"}},{"t":"case","label":"Wayte v. United States","cite":"470 U.S. 598","y":1985,"id":"1984/83-1292","sc":1,"sum":"The Supreme Court held, 7-to-2, that the government's passive enforcement policy was constitutional.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Wilkinson v. Austin","cite":"545 U.S. 209","y":2005,"id":"2004/04-495","sc":1,"sum":"The Court held that the procedures by which the New Policy classified prisoners for placement at the facility provided sufficient protection to comply with the due process clause. The Court reasoned that procedural protections afforded to prisoners were necessarily limited, and that the New Policy sufficiently minimized risk of erroneous placement.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Wong Wing v. United States","cite":"163 U.S. 228","y":1896,"id":"1850-1900/163us228","sc":1,"sum":"Consequently, the imprisonment provisions of the Act are void.","sumSrc":"Oyez","by":{"0":"26, 35","1":"13, 15"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"0":"42, 46"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"passim","1":"3, 6, 10"}},{"t":"law","label":"Pub. L. No. 87-301","url":"https://www.govinfo.gov/link/statute/75/651","by":{"0":"36"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"0":"10"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"41"}},{"t":"usc","label":"6 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/6/101","stext":{"head":"§101. Definitions","paras":[[0,"In this chapter, the following definitions apply:"],[1,"(1) Each of the terms \"American homeland\" and \"homeland\" means the United States."],[1,"(2) The term \"appropriate congressional committee\" means any committee of the House of Representatives or the Senate having legislative or oversight jurisdiction under the Rules of the House of Representatives or the Senate, respectively, over the matter concerned."],[1,"(3) The term \"assets\" includes contracts, facilities, property, records, unobligated or unexpended balances of appropriations, and other funds or resources (other than personnel)."],[1,"(4) The term \"critical infrastructure\" has the meaning given that term in section 5195c(e) of title 42."],[1,"(5) The term \"Department\" means the Department of Homeland Security."],[1,"(6) The term \"emergency response providers\" includes Federal, State, and local governmental and nongovernmental emergency public safety, fire, law enforcement, emergency response, emergency medical (including hospital emergency facilities), and related personnel, agencies, and authorities."],[1,"(7) The term \"EMP\" means an electromagnetic pulse caused by a nuclear device or nonnuclear device, including such a pulse caused by an act of terrorism."],[1,"(8) The term \"executive agency\" means an executive agency and a military department, as defined, respectively, in sections 105 and 102 of title 5."],[1,"(9) The term \"functions\" includes authorities, powers, rights, privileges, immunities, programs, projects, activities, duties, and responsibilities."],[1,"(10) The term \"GMD\" means a geomagnetic disturbance caused by a solar storm or another naturally occurring phenomenon."],[1,"(11) The term \"intelligence component of the Department\" means any element or entity of the Department that collects, gathers, processes, analyzes, produces, or disseminates intelligence information within the scope of the information sharing environment, including homeland security information, terrorism information, and weapons of mass destruction information, or national intelligence, as defined under section 3003(5) of title 50, except—"],[2,"(A) the United States Secret Service; and"],[2,"(B) the Coast Guard, when operating under the direct authority of the Secretary of Defense or Secretary of the Navy pursuant to section 3 1 of title 14, except that nothing in this paragraph shall affect or diminish the authority and responsibilities of the Commandant of the Coast Guard to command or control the Coast Guard as an armed force or the authority of the Director of National Intelligence with respect to the Coast Guard as an element of the intelligence community (as defined under section 3003(4) of title 50.2"],[1,"(12) The term \"key resources\" means publicly or privately controlled resources essential to the minimal operations of the economy and government."],[1,"(13) The term \"local government\" means—"],[2,"(A) a county, municipality, city, town, township, local public authority, school district, special district, intrastate district, council of governments (regardless of whether the council of governments is incorporated as a nonprofit corporation under State law), regional or interstate government entity, or agency or instrumentality of a local government;"],[2,"(B) an Indian tribe or authorized tribal organization, or in Alaska a Native village or Alaska Regional Native Corporation; and"],[2,"(C) a rural community, unincorporated town or village, or other public entity."],[1,"(14) The term \"major disaster\" has the meaning given in section 5122(2) of title 42."],[1,"(15) The term \"personnel\" means officers and employees."],[1,"(16) The term \"Secretary\" means the Secretary of Homeland Security."],[1,"(17) The term \"State\" means any State of the United States, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, the Commonwealth of the Northern Mariana Islands, and any possession of the United States."],[1,"(18) The term \"terrorism\" means any activity that—"],[2,"(A) involves an act that—"],[3,"(i) is dangerous to human life or potentially destructive of critical infrastructure or key resources; and"],[3,"(ii) is a violation of the criminal laws of the United States or of any State or other subdivision of the United States; and"],[2,"(B) appears to be intended—"],[3,"(i) to intimidate or coerce a civilian population;"],[3,"(ii) to influence the policy of a government by intimidation or coercion; or"],[3,"(iii) to affect the conduct of a government by mass destruction, assassination, or kidnapping."],[1,"(19)(A) The term \"United States\", when used in a geographic sense, means any State of the United States, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, the Commonwealth of the Northern Mariana Islands, any possession of the United States, and any waters within the jurisdiction of the United States."],[1,"(B) Nothing in this paragraph or any other provision of this chapter shall be construed to modify the definition of \"United States\" for the purposes of the Immigration and Nationality Act [8 U.S.C. 1101 et seq.] or any other immigration or nationality law."],[1,"(20) The term \"voluntary preparedness standards\" means a common set of criteria for preparedness, disaster management, emergency management, and business continuity programs, such as the American National Standards Institute's National Fire Protection Association Standard on Disaster/Emergency Management and Business Continuity Programs (ANSI/NFPA 1600)."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/6/101?type=usc&year=mostrecent&link-type=html"},"head":"§101. Definitions","tname":"Domestic Security","by":{"0":"37","1":"17"}},{"t":"usc","label":"6 U.S.C. § 236","url":"https://www.law.cornell.edu/uscode/text/6/236","subs":["(b)","(e)","(b)(1)","(c)(1)"],"stext":{"head":"§236. Visa issuance","paras":[[0,"(a) Definition"],[0,"In this subsection,1 the term \"consular office\" 2 has the meaning given that term under section 101(a)(9) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(9))."],[0,"(b) In general"],[0,"Notwithstanding section 104(a) of the Immigration and Nationality Act (8 U.S.C. 1104(a)) or any other provision of law, and except as provided in subsection (c) of this section, the Secretary—"],[1,"(1) shall be vested exclusively with all authorities to issue regulations with respect to, administer, and enforce the provisions of such Act [8 U.S.C. 1101 et seq.], and of all other immigration and nationality laws, relating to the functions of consular officers of the United States in connection with the granting or refusal of visas, and shall have the authority to refuse visas in accordance with law and to develop programs of homeland security training for consular officers (in addition to consular training provided by the Secretary of State), which authorities shall be exercised through the Secretary of State, except that the Secretary shall not have authority to alter or reverse the decision of a consular officer to refuse a visa to an alien; and"],[1,"(2) shall have authority to confer or impose upon any officer or employee of the United States, with the consent of the head of the executive agency under whose jurisdiction such officer or employee is serving, any of the functions specified in paragraph (1)."],[0,"(c) Authority of the Secretary of State"],[0,"(1) In general"],[1,"Notwithstanding subsection (b), the Secretary of State may direct a consular officer to refuse a visa to an alien if the Secretary of State deems such refusal necessary or advisable in the foreign policy or security interests of the United States."],[0,"(2) Construction regarding authority"],[1,"Nothing in this section, consistent with the Secretary of Homeland Security's authority to refuse visas in accordance with law, shall be construed as affecting the authorities of the Secretary of State under the following provisions of law:"],[2,"(A) Section 101(a)(15)(A) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(15)(A))."],[2,"(B) Section 204(d)(2) of the Immigration and Nationality Act (8 U.S.C. 1154) (as it will take effect upon the entry into force of the Convention on Protection of Children and Cooperation in Respect to Inter-Country adoption)."],[2,"(C) Section 212(a)(3)(B)(i)(IV)(bb) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(B)(i)(IV)(bb))."],[2,"(D) Section 212(a)(3)(B)(i)(VI) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(B)(i)(VI))."],[2,"(E) Section 212(a)(3)(B)(vi)(II) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(B)(vi)(II))."],[2,"(F) Section 212(a)(3)(C) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(C))."],[2,"(G) Section 212(a)(10)(C) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(10)(C))."],[2,"(H) Section 212(f) of the Immigration and Nationality Act (8 U.S.C. 1182(f))."],[2,"(I) Section 219(a) of the Immigration and Nationality Act (8 U.S.C. 1189(a))."],[2,"(J) Section 237(a)(4)(C) of the Immigration and Nationality Act (8 U.S.C. 1227(a)(4)(C))."],[2,"(K) Section 401 of the Cuban Liberty and Democratic Solidarity (LIBERTAD) Act of 1996 [22 U.S.C. 6091]."],[2,"(L) Section 613 of the Departments of Commerce, Justice, and State, the Judiciary and Related Agencies Appropriations Act, 1999 3 (as contained in section 101(b) of division A of Public Law 105–277) (Omnibus Consolidated and Emergency Supplemental Appropriations Act, 1999); 112 Stat. 2681; H.R. 4328 (originally H.R. 4276) as amended by section 617 of Public Law 106–553."],[2,"(M) Section 103(f) of the Chemical Weapon Convention Implementation Act of 1998 [22 U.S.C. 6713(f)] (112 Stat. 2681–865)."],[2,"(N) Section 801 of H.R. 3427, the Admiral James W. Nance and Meg Donovan Foreign Relations Authorization Act, Fiscal Years 2000 and 2001 [8 U.S.C. 1182e], as enacted by reference in Public Law 106–113."],[2,"(O) Section 568 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 2002 (Public Law 107–115)."],[2,"(P) Section 51 of the State Department Basic Authorities Act of 1956 (22 U.S.C. 2723)."],[0,"(d) Consular officers and chiefs of missions"],[0,"(1) In general"],[1,"Nothing in this section may be construed to alter or affect—"],[2,"(A) the employment status of consular officers as employees of the Department of State; or"],[2,"(B) the authority of a chief of mission under section 207 of the Foreign Service Act of 1980 (22 U.S.C. 3927)."],[0,"(2) Construction regarding delegation of authority"],[1,"Nothing in this section shall be construed to affect any delegation of authority to the Secretary of State by the President pursuant to any proclamation issued under section 212(f) of the Immigration and Nationality Act (8 U.S.C. 1182(f)), consistent with the Secretary of Homeland Security's authority to refuse visas in accordance with law."],[0,"(e) Assignment of Homeland Security employees to diplomatic and consular posts"],[0,"(1) In general"],[1,"The Secretary is authorized to assign employees of the Department to each diplomatic and consular post at which visas are issued, unless the Secretary determines that such an assignment at a particular post would not promote homeland security."],[0,"(2) Functions"],[1,"Employees assigned under paragraph (1) shall perform the following functions:"],[2,"(A) Provide expert advice and training to consular officers regarding specific security threats relating to the adjudication of individual visa applications or classes of applications."],[2,"(B) Review any such applications, either on the initiative of the employee of the Department or upon request by a consular officer or other person charged with adjudicating such applications."],[2,"(C) Conduct investigations with respect to consular matters under the jurisdiction of the Secretary."],[0,"(3) Evaluation of consular officers"],[1,"The Secretary of State shall evaluate, in consultation with the Secretary, as deemed appropriate by the Secretary, the performance of consular officers with respect to the processing and adjudication of applications for visas in accordance with performance standards developed by the Secretary for these procedures."],[0,"(4) Report"],[1,"The Secretary shall, on an annual basis, submit a report to Congress that describes the basis for each determination under paragraph (1) that the assignment of an employee of the Department at a particular diplomatic post would not promote homeland security."],[0,"(5) Permanent assignment; participation in terrorist lookout committee"],[1,"When appropriate, employees of the Department assigned to perform functions described in paragraph (2) may be assigned permanently to overseas diplomatic or consular posts with country-specific or regional responsibility. If the Secretary so directs, any such employee, when present at an overseas post, shall participate in the terrorist lookout committee established under section 304 of the Enhanced Border Security and Visa Entry Reform Act of 2002 (8 U.S.C. 1733)."],[0,"(6) Training and hiring"],[0,"(A) In general"],[2,"The Secretary shall ensure, to the extent possible, that any employees of the Department assigned to perform functions under paragraph (2) and, as appropriate, consular officers, shall be provided the necessary training to enable them to carry out such functions, including training in foreign languages, interview techniques, and fraud detection techniques, in conditions in the particular country where each employee is assigned, and in other appropriate areas of study."],[0,"(B) Use of Center"],[2,"The Secretary is authorized to use the National Foreign Affairs Training Center, on a reimbursable basis, to obtain the training described in subparagraph (A)."],[0,"(7) Report"],[1,"Not later than 1 year after November 25, 2002, the Secretary and the Secretary of State shall submit to Congress—"],[2,"(A) a report on the implementation of this subsection; and"],[2,"(B) any legislative proposals necessary to further the objectives of this subsection."],[0,"(8) Effective date"],[1,"This subsection shall take effect on the earlier of—"],[2,"(A) the date on which the President publishes notice in the Federal Register that the President has submitted a report to Congress setting forth a memorandum of understanding between the Secretary and the Secretary of State governing the implementation of this section; or"],[2,"(B) the date occurring 1 year after November 25, 2002."],[0,"(f) No creation of private right of action"],[0,"Nothing in this section shall be construed to create or authorize a private right of action to challenge a decision of a consular officer or other United States official or employee to grant or deny a visa."],[0,"(g) Study regarding use of foreign nationals"],[0,"(1) In general"],[1,"The Secretary of Homeland Security shall conduct a study of the role of foreign nationals in the granting or refusal of visas and other documents authorizing entry of aliens into the United States. The study shall address the following:"],[2,"(A) The proper role, if any, of foreign nationals in the process of rendering decisions on such grants and refusals."],[2,"(B) Any security concerns involving the employment of foreign nationals."],[2,"(C) Whether there are cost-effective alternatives to the use of foreign nationals."],[0,"(2) Report"],[1,"Not later than 1 year after November 25, 2002, the Secretary shall submit a report containing the findings of the study conducted under paragraph (1) to the Committee on the Judiciary, the Committee on International Relations, and the Committee on Government Reform of the House of Representatives, and the Committee on the Judiciary, the Committee on Foreign Relations, and the Committee on Government 4 Affairs of the Senate."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/6/236?type=usc&year=mostrecent&link-type=html"},"head":"§236. Visa issuance","tname":"Domestic Security","by":{"0":"37, 37, 37, 7, 4, 7, 4, 7","1":"17, 17"}},{"t":"usc","label":"6 U.S.C. § 251","url":"https://www.law.cornell.edu/uscode/text/6/251","by":{"0":"3"}},{"t":"usc","label":"6 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/6/271","subs":["(b)"],"by":{"0":"3"}},{"t":"usc","label":"6 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/6/542","by":{"0":"3"}},{"t":"usc","label":"6 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/6/557","by":{"0":"3"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"2","1":"2, 10"}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/8/1104","subs":["(a)(1)"],"by":{"0":"2, 7"}},{"t":"usc","label":"8 U.S.C. § 1105","url":"https://www.law.cornell.edu/uscode/text/8/1105","subs":["(a)","(b)(1)"],"stext":{"head":"§1105. Liaison with internal security officers; data exchange","paras":[[0,"(a) In general"],[0,"The Commissioner and the Administrator shall have authority to maintain direct and continuous liaison with the Directors of the Federal Bureau of Investigation and the Central Intelligence Agency and with other internal security officers of the Government for the purpose of obtaining and exchanging information for use in enforcing the provisions of this chapter in the interest of the internal and border security of the United States. The Commissioner and the Administrator shall maintain direct and continuous liaison with each other with a view to a coordinated, uniform, and efficient administration of this chapter, and all other immigration and nationality laws."],[0,"(b) Access to National Crime Information Center files"],[0,"(1) The Attorney General and the Director of the Federal Bureau of Investigation shall provide the Department of State and the Service access to the criminal history record information contained in the National Crime Information Center's Interstate Identification Index (NCIC-III), Wanted Persons File, and to any other files maintained by the National Crime Information Center that may be mutually agreed upon by the Attorney General and the agency receiving the access, for the purpose of determining whether or not a visa applicant or applicant for admission has a criminal history record indexed in any such file."],[0,"(2) Such access shall be provided by means of extracts of the records for placement in the automated visa lookout or other appropriate database, and shall be provided without any fee or charge."],[0,"(3) The Federal Bureau of Investigation shall provide periodic updates of the extracts at intervals mutually agreed upon with the agency receiving the access. Upon receipt of such updated extracts, the receiving agency shall make corresponding updates to its database and destroy previously provided extracts."],[0,"(4) Access to an extract does not entitle the Department of State to obtain the full content of the corresponding automated criminal history record. To obtain the full content of a criminal history record, the Department of State shall submit the applicant's fingerprints and any appropriate fingerprint processing fee authorized by law to the Criminal Justice Information Services Division of the Federal Bureau of Investigation."],[0,"(c) Reconsideration upon development of more cost effective means of sharing information"],[0,"The provision of the extracts described in subsection (b) may be reconsidered by the Attorney General and the receiving agency upon the development and deployment of a more cost-effective and efficient means of sharing the information."],[0,"(d) Regulations"],[0,"For purposes of administering this section, the Department of State shall, prior to receiving access to NCIC data but not later than 4 months after October 26, 2001, promulgate final regulations—"],[1,"(1) to implement procedures for the taking of fingerprints; and"],[1,"(2) to establish the conditions for the use of the information received from the Federal Bureau of Investigation, in order—"],[2,"(A) to limit the redissemination of such information;"],[2,"(B) to ensure that such information is used solely to determine whether or not to issue a visa to an alien or to admit an alien to the United States;"],[2,"(C) to ensure the security, confidentiality, and destruction of such information; and"],[2,"(D) to protect any privacy rights of individuals who are subjects of such information."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1105?type=usc&year=mostrecent&link-type=html"},"head":"§1105. Liaison with internal security officers; data exchange","tname":"Aliens and Nationality","by":{"0":"48, 5, 48, 48","1":"16"}},{"t":"usc","label":"8 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/8/1151","subs":["(b)","(b)(2)(A)(i)","(d)"],"by":{"0":"18, 2, 3, 19"}},{"t":"usc","label":"8 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/8/1153","subs":["(a)","(b)"],"by":{"0":"2, 19, 2"}},{"t":"usc","label":"8 U.S.C. § 1154","url":"https://www.law.cornell.edu/uscode/text/8/1154","subs":["(a)(1)","(a)(1)(A)(viii)","(a)(1)(B)(i)(II)","(b)","(a)"],"stext":{"head":"§1154. Procedure for granting immigrant status","paras":[[0,"(a) Petitioning procedure"],[0,"(1)(A)(i) Except as provided in clause (viii), any citizen of the United States claiming that an alien is entitled to classification by reason of a relationship described in paragraph (1), (3), or (4) of section 1153(a) of this title or to an immediate relative status under section 1151(b)(2)(A)(i) of this title may file a petition with the Attorney General for such classification."],[0,"(ii) An alien spouse described in the second sentence of section 1151(b)(2)(A)(i) of this title also may file a petition with the Attorney General under this subparagraph for classification of the alien (and the alien's children) under such section."],[0,"(iii)(I) An alien who is described in subclause (II) may file a petition with the Attorney General under this clause for classification of the alien (and any child of the alien) if the alien demonstrates to the Attorney General that—"],[1,"(aa) the marriage or the intent to marry the United States citizen was entered into in good faith by the alien; and"],[1,"(bb) during the marriage or relationship intended by the alien to be legally a marriage, the alien or a child of the alien has been battered or has been the subject of extreme cruelty perpetrated by the alien's spouse or intended spouse."],[0,"(II) For purposes of subclause (I), an alien described in this subclause is an alien—"],[1,"(aa)(AA) who is the spouse of a citizen of the United States;"],[1,"(BB) who believed that he or she had married a citizen of the United States and with whom a marriage ceremony was actually performed and who otherwise meets any applicable requirements under this chapter to establish the existence of and bona fides of a marriage, but whose marriage is not legitimate solely because of the bigamy of such citizen of the United States; or"],[1,"(CC) who was a bona fide spouse of a United States citizen within the past 2 years and—"],[2,"(aaa) whose spouse died within the past 2 years;"],[2,"(bbb) whose spouse lost or renounced citizenship status within the past 2 years related to an incident of domestic violence; or"],[2,"(ccc) who demonstrates a connection between the legal termination of the marriage within the past 2 years and battering or extreme cruelty by the United States citizen spouse;"],[1,"(bb) who is a person of good moral character;"],[1,"(cc) who is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title or who would have been so classified but for the bigamy of the citizen of the United States that the alien intended to marry; and"],[1,"(dd) who has resided with the alien's spouse or intended spouse."],[0,"(iv) An alien who is the child of a citizen of the United States, or who was a child of a United States citizen parent who within the past 2 years lost or renounced citizenship status related to an incident of domestic violence, and who is a person of good moral character, who is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title, and who resides, or has resided in the past, with the citizen parent may file a petition with the Attorney General under this subparagraph for classification of the alien (and any child of the alien) under such section if the alien demonstrates to the Attorney General that the alien has been battered by or has been the subject of extreme cruelty perpetrated by the alien's citizen parent. For purposes of this clause, residence includes any period of visitation."],[0,"(v) An alien who—"],[1,"(I) is the spouse, intended spouse, or child living abroad of a citizen who—"],[2,"(aa) is an employee of the United States Government;"],[2,"(bb) is a member of the uniformed services (as defined in section 101(a) of title 10); or"],[2,"(cc) has subjected the alien or the alien's child to battery or extreme cruelty in the United States; and"],[1,"(II) is eligible to file a petition under clause (iii) or (iv),"],[0,"shall file such petition with the Attorney General under the procedures that apply to self-petitioners under clause (iii) or (iv), as applicable."],[0,"(vi) For the purposes of any petition filed under clause (iii) or (iv), the denaturalization, loss or renunciation of citizenship, death of the abuser, divorce, or changes to the abuser's citizenship status after filing of the petition shall not adversely affect the approval of the petition, and for approved petitions shall not preclude the classification of the eligible self-petitioning spouse or child as an immediate relative or affect the alien's ability to adjust status under subsections (a) and (c) of section 1255 of this title or obtain status as a lawful permanent resident based on the approved self-petition under such clauses."],[0,"(vii) An alien may file a petition with the Secretary of Homeland Security under this subparagraph for classification of the alien under section 1151(b)(2)(A)(i) of this title if the alien—"],[1,"(I) is the parent of a citizen of the United States or was a parent of a citizen of the United States who, within the past 2 years, lost or renounced citizenship status related to an incident of domestic violence or died;"],[1,"(II) is a person of good moral character;"],[1,"(III) is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title;"],[1,"(IV) resides, or has resided, with the citizen daughter or son; and"],[1,"(V) demonstrates that the alien has been battered or subject to extreme cruelty by the citizen daughter or son."],[0,"(viii)(I) Clause (i) shall not apply to a citizen of the United States who has been convicted of a specified offense against a minor, unless the Secretary of Homeland Security, in the Secretary's sole and unreviewable discretion, determines that the citizen poses no risk to the alien with respect to whom a petition described in clause (i) is filed."],[0,"(II) For purposes of subclause (I), the term \"specified offense against a minor\" is defined as in section 20911 of title 34."],[0,"(B)(i)(I) Except as provided in subclause (II), any alien lawfully admitted for permanent residence claiming that an alien is entitled to a classification by reason of the relationship described in section 1153(a)(2) of this title may file a petition with the Attorney General for such classification."],[0,"(I) 1 Subclause (I) shall not apply in the case of an alien lawfully admitted for permanent residence who has been convicted of a specified offense against a minor (as defined in subparagraph (A)(viii)(II)), unless the Secretary of Homeland Security, in the Secretary's sole and unreviewable discretion, determines that such person poses no risk to the alien with respect to whom a petition described in subclause (I) is filed."],[0,"(ii)(I) An alien who is described in subclause (II) may file a petition with the Attorney General under this clause for classification of the alien (and any child of the alien) if such a child has not been classified under clause (iii) of section 1153(a)(2)(A) of this title and if the alien demonstrates to the Attorney General that—"],[1,"(aa) the marriage or the intent to marry the lawful permanent resident was entered into in good faith by the alien; and"],[1,"(bb) during the marriage or relationship intended by the alien to be legally a marriage, the alien or a child of the alien has been battered or has been the subject of extreme cruelty perpetrated by the alien's spouse or intended spouse."],[0,"(II) For purposes of subclause (I), an alien described in this paragraph is an alien—"],[1,"(aa)(AA) who is the spouse of a lawful permanent resident of the United States; or"],[1,"(BB) who believed that he or she had married a lawful permanent resident of the United States and with whom a marriage ceremony was actually performed and who otherwise meets any applicable requirements under this chapter to establish the existence of and bona fides of a marriage, but whose marriage is not legitimate solely because of the bigamy of such lawful permanent resident of the United States; or"],[1,"(CC) who was a bona fide spouse of a lawful permanent resident within the past 2 years and—"],[2,"(aaa) whose spouse lost status within the past 2 years due to an incident of domestic violence; or"],[2,"(bbb) who demonstrates a connection between the legal termination of the marriage within the past 2 years and battering or extreme cruelty by the lawful permanent resident spouse;"],[1,"(bb) who is a person of good moral character;"],[1,"(cc) who is eligible to be classified as a spouse of an alien lawfully admitted for permanent residence under section 1153(a)(2)(A) of this title or who would have been so classified but for the bigamy of the lawful permanent resident of the United States that the alien intended to marry; and"],[1,"(dd) who has resided with the alien's spouse or intended spouse."],[0,"(iii) An alien who is the child of an alien lawfully admitted for permanent residence, or who was the child of a lawful permanent resident who within the past 2 years lost lawful permanent resident status due to an incident of domestic violence, and who is a person of good moral character, who is eligible for classification under section 1153(a)(2)(A) of this title, and who resides, or has resided in the past, with the alien's permanent resident alien parent may file a petition with the Attorney General under this subparagraph for classification of the alien (and any child of the alien) under such section if the alien demonstrates to the Attorney General that the alien has been battered by or has been the subject of extreme cruelty perpetrated by the alien's permanent resident parent."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1154?type=usc&year=mostrecent&link-type=html"},"head":"§1154. Procedure for granting immigrant status","tname":"Aliens and Nationality","by":{"0":"3, 18, 3, 3, 18","1":"6"}},{"t":"usc","label":"8 U.S.C. § 1181","url":"https://www.law.cornell.edu/uscode/text/8/1181","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)","(a)(1)(A)","(a)(2)","(a)(3)","(a)(3)(B)","(a)(3)(B)(i)","(a)(3)(B)(i)(I)","(a)(3)(B)(i)(VIII)","(a)(3)(B)(i)(IX)","(a)(3)(B)(ii)","(a)(3)(B)(iii)","(a)(3)(B)(iv)","(a)(3)(B)(iv)(IV)","(a)(3)(B)(v)","(a)(3)(B)(vi)","(a)(7)","(a)(9)(B)(v)","(b)","(b)(1)","(b)(3)","(d)(3)(B)(i)","(g)","(h)","(i)","(a)(2)(A)","(a)(2)(B)","(a)(3)(B)(i)(VI)","(b)(1)(B)","(d)","(d)(3)(A)(i)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"5, 5, 5, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 5, 5, 5, 5, 5, 5, 5, 5","1":"5, 17, 11, 11, 11, 11, 22, 2, 16, 20, 22, 5, 5, 5, 18, 5, 15"}},{"t":"usc","label":"8 U.S.C. § 1187","url":"https://www.law.cornell.edu/uscode/text/8/1187","subs":["(c)","(c)(2)(F)"],"by":{"0":"37, 48"}},{"t":"usc","label":"8 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/8/1201","subs":["(a)","(a)(1)","(c)","(d)","(g)","(i)"],"by":{"0":"18, 19, 3, 4, 19, 19, 5, 19, 39, 52, 8, 37"}},{"t":"usc","label":"8 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/8/1202","subs":["(a)","(b)","(c)","(d)","(e)","(h)"],"stext":{"head":"§1202. Application for visas","paras":[[0,"(a) Immigrant visas"],[0,"Every alien applying for an immigrant visa and for alien registration shall make application therefor in such form and manner and at such place as shall be by regulations prescribed. In the application the alien shall state his full and true name, and any other name which he has used or by which he has been known; age and sex; the date and place of his birth; and such additional information necessary to the identification of the applicant and the enforcement of the immigration and nationality laws as may be by regulations prescribed."],[0,"(b) Other documentary evidence for immigrant visa"],[0,"Every alien applying for an immigrant visa shall present a valid unexpired passport or other suitable travel document, or document of identity and nationality, if such document is required under the regulations issued by the Secretary of State. The immigrant shall furnish to the consular officer with his application a copy of a certification by the appropriate police authorities stating what their records show concerning the immigrant; a certified copy of any existing prison record, military record, and record of his birth; and a certified copy of all other records or documents concerning him or his case which may be required by the consular officer. The copy of each document so furnished shall be permanently attached to the application and become a part thereof. In the event that the immigrant establishes to the satisfaction of the consular officer that any document or record required by this subsection is unobtainable, the consular officer may permit the immigrant to submit in lieu of such document or record other satisfactory evidence of the fact to which such document or record would, if obtainable, pertain. All immigrant visa applications shall be reviewed and adjudicated by a consular officer."],[0,"(c) Nonimmigrant visas; nonimmigrant registration; form, manner and contents of application"],[0,"Every alien applying for a nonimmigrant visa and for alien registration shall make application therefor in such form and manner as shall be by regulations prescribed. In the application the alien shall state his full and true name, the date and place of birth, his nationality, the purpose and length of his intended stay in the United States; his marital status; and such additional information necessary to the identification of the applicant, the determination of his eligibility for a nonimmigrant visa, and the enforcement of the immigration and nationality laws as may be by regulations prescribed. The alien shall provide complete and accurate information in response to any request for information contained in the application. At the discretion of the Secretary of State, application forms for the various classes of nonimmigrant admissions described in section 1101(a)(15) of this title may vary according to the class of visa being requested."],[0,"(d) Other documentary evidence for nonimmigrant visa"],[0,"Every alien applying for a nonimmigrant visa and alien registration shall furnish to the consular officer, with his application, a certified copy of such documents pertaining to him as may be by regulations required. All nonimmigrant visa applications shall be reviewed and adjudicated by a consular officer."],[0,"(e) Signing and verification of application"],[0,"Except as may be otherwise prescribed by regulations, each application for an immigrant visa shall be signed by the applicant in the presence of the consular officer, and verified by the oath of the applicant administered by the consular officer. The application for an immigrant visa, when visaed by the consular officer, shall become the immigrant visa. The application for a nonimmigrant visa or other documentation as a nonimmigrant shall be disposed of as may be by regulations prescribed. The issuance of a nonimmigrant visa shall, except as may be otherwise by regulations prescribed, be evidenced by a stamp, or other 1 placed in the alien's passport."],[0,"(f) Confidential nature of records"],[0,"The records of the Department of State and of diplomatic and consular offices of the United States pertaining to the issuance or refusal of visas or permits to enter the United States shall be considered confidential and shall be used only for the formulation, amendment, administration, or enforcement of the immigration, nationality, and other laws of the United States, except that—"],[1,"(1) in the discretion of the Secretary of State certified copies of such records may be made available to a court which certifies that the information contained in such records is needed by the court in the interest of the ends of justice in a case pending before the court.2"],[1,"(2) the Secretary of State, in the Secretary's discretion and on the basis of reciprocity, may provide to a foreign government information in the Department of State's computerized visa lookout database and, when necessary and appropriate, other records covered by this section related to information in the database—"],[2,"(A) with regard to individual aliens, at any time on a case-by-case basis for the purpose of preventing, investigating, or punishing acts that would constitute a crime in the United States, including, but not limited to, terrorism or trafficking in controlled substances, persons, or illicit weapons; or"],[2,"(B) with regard to any or all aliens in the database, pursuant to such conditions as the Secretary of State shall establish in an agreement with the foreign government in which that government agrees to use such information and records for the purposes described in subparagraph (A) or to deny visas to persons who would be inadmissible to the United States."],[0,"(g) Nonimmigrant visa void at conclusion of authorized period of stay"],[0,"(1) In the case of an alien who has been admitted on the basis of a nonimmigrant visa and remained in the United States beyond the period of stay authorized by the Attorney General, such visa shall be void beginning after the conclusion of such period of stay."],[0,"(2) An alien described in paragraph (1) shall be ineligible to be readmitted to the United States as a nonimmigrant, except—"],[1,"(A) on the basis of a visa (other than the visa described in paragraph (1)) issued in a consular office located in the country of the alien's nationality (or, if there is no office in such country, in such other consular office as the Secretary of State shall specify); or"],[1,"(B) where extraordinary circumstances are found by the Secretary of State to exist."],[0,"(h) In person interview with consular officer"],[0,"Notwithstanding any other provision of this chapter, the Secretary of State shall require every alien applying for a nonimmigrant visa—"],[1,"(1) who is at least 14 years of age and not more than 79 years of age to submit to an in person interview with a consular officer unless the requirement for such interview is waived—"],[2,"(A) by a consular official and such alien is—"],[3,"(i) within that class of nonimmigrants enumerated in subparagraph (A) or (G) of section 1101(a)(15) of this title;"],[3,"(ii) within the NATO visa category;"],[3,"(iii) within that class of nonimmigrants enumerated in section 1101(a)(15)(C)(iii) 3 of this title (referred to as the \"C–3 visa\" category); or"],[3,"(iv) granted a diplomatic or official visa on a diplomatic or official passport or on the equivalent thereof;"],[2,"(B) by a consular official and such alien is applying for a visa—"],[3,"(i) not more than 12 months after the date on which such alien's prior visa expired;"],[3,"(ii) for the visa classification for which such prior visa was issued;"],[3,"(iii) from the consular post located in the country of such alien's usual residence, unless otherwise prescribed in regulations that require an applicant to apply for a visa in the country of which such applicant is a national; and"],[3,"(iv) the consular officer has no indication that such alien has not complied with the immigration laws and regulations of the United States; or"],[2,"(C) by the Secretary of State if the Secretary determines that such waiver is—"],[3,"(i) in the national interest of the United States; or"],[3,"(ii) necessary as a result of unusual or emergent circumstances; and"],[1,"(2) notwithstanding paragraph (1), to submit to an in person interview with a consular officer if such alien—"],[2,"(A) is not a national or resident of the country in which such alien is applying for a visa;"],[2,"(B) was previously refused a visa, unless such refusal was overcome or a waiver of ineligibility has been obtained;"],[2,"(C) is listed in the Consular Lookout and Support System (or successor system at the Department of State);"],[2,"(D) is a national of a country officially designated by the Secretary of State as a state sponsor of terrorism, except such nationals who possess nationalities of countries that are not designated as state sponsors of terrorism;"],[2,"(E) requires a security advisory opinion or other Department of State clearance, unless such alien is—"],[3,"(i) within that class of nonimmigrants enumerated in subparagraph (A) or (G) of section 1101(a)(15) of this title;"],[3,"(ii) within the NATO visa category;"],[3,"(iii) within that class of nonimmigrants enumerated in section 1101(a)(15)(C)(iii) 3 of this title (referred to as the \"C–3 visa\" category); or"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1202?type=usc&year=mostrecent&link-type=html"},"head":"§1202. Application for visas","tname":"Aliens and Nationality","by":{"0":"3, 4, 18, 19, 4, 19, 3, 3, 4, 19, 19, 41, 48, 3","1":"18"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","by":{"0":"31"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/8/1361","by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1551","url":"https://www.law.cornell.edu/uscode/text/8/1551","by":{"0":"3"}},{"t":"law","label":"Visa Waiver Permanent Program Act, Pub. L. No. 106-396","url":"https://www.govinfo.gov/link/plaw/106/public/396","by":{"0":"37"}},{"t":"usc","label":"22 U.S.C. § 2723","url":"https://www.law.cornell.edu/uscode/text/22/2723","subs":["(a)(1)","(b)"],"by":{"0":"6, 6"}},{"t":"usc","label":"22 U.S.C. § 4807","url":"https://www.law.cornell.edu/uscode/text/22/4807","by":{"0":"49"}},{"t":"reg","label":"3 C.F.R. pt. 214","url":"https://www.ecfr.gov/current/title-3/part-214","by":{"0":"49"}},{"t":"reg","label":"3 C.F.R. pt. 198","url":"https://www.ecfr.gov/current/title-3/part-198","by":{"0":"49"}},{"t":"case","label":"Florida v. Harris","cite":"133 S. Ct. 1050","y":2013,"id":"2012/11-817","sc":1,"sum":"The Court found that police officers do not need to show evidence of a drug-detection dog's reliability to prove probable cause.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Gerstein v. Pugh","cite":"420 U.S. 103","y":1975,"id":"1973/73-477","sc":1,"sum":"The Court held that the Fourth Amendment entitles a person arrested without a warrant and charged by information to a timely preliminary hearing on probable cause.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"sum":"The Court held that individuals held in military confinement by the national government have a right, under the Fifth Amendment, to appeal that confinement in front of a neutral decision-making body.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Holder v. Martinez Gutierrez","cite":"132 S. Ct. 2011","y":2012,"url":"https://www.courtlistener.com/c/S.%20Ct./132/2011/","sc":1,"by":{"1":"8"}},{"t":"case","label":"Ibrahim v. DHS","cite":"2014 WL 6609111","y":2014,"court":"N.D. Cal. Jan. 14","ar":2,"sum":"Explaining that visa denial by consular officer was based on classified information that was separate and apart from mistaken inclusion of plaintiff on no-fly list.","sumSrc":"brief:1","by":{"1":"16"}},{"t":"case","label":"Mackey v. Montrym","cite":"443 U.S. 1","y":1979,"id":"1978/77-69","sc":1,"sum":"The Court held that the lower court erred in finding that the Massachusetts statute deprived Montrym of his Fourteenth Amendment right to Due Process.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the IIRIRA deprives federal courts of jurisdiction over the selective-enforcement claim.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Saenz v. Roe","cite":"526 U.S. 489","y":1999,"id":"1998/98-97","sc":1,"sum":"In a 7-to-2 decision, the Court held that the Fourteenth Amendment protects the right to travel in three ways by: allowing citizens to move freely between states, securing the right to be treated equally in all states when visiting, and securing the rights of new citizens to be treated like long-time citizens of a state.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"case","label":"Singh-Kaur v. Ashcroft","cite":"385 F.3d 293","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/385/293/","by":{"1":"22"}},{"t":"case","label":"Superintendent v. Hill","cite":"472 U.S. 445","y":1985,"id":"1984/84-438","sc":1,"sum":"Respondent inmates in a Massachusetts state prison each received disciplinary reports charging them with assaulting another inmate. At separate hearings, a prison disciplinary board heard testimony from a prison guard and received his written report. According to this evidence the guard heard some commotion in a prison walkway and, upon investigating, discovered an inmate who evidently had just been assaulted, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Thompson v. Thompson","cite":"218 U.S. 611","y":1910,"id":"scdb/1910-039","sc":1,"sum":"At common law husband and wife were regarded as one, the legal existence of the latter during coverture being merged in that of the former.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"6"}},{"t":"case","label":"Turner v. Safley","cite":"482 U.S. 78","y":1987,"id":"1986/85-1384","sc":1,"ar":2,"sum":"Justice O’Connor further reasoned that the restrictions did not deprive inmates of all means of expression, only limiting correspondence with a particular class of people. She argued that the Eighth Circuit failed to consider the impact easing the restriction might have on the liberty and safety of prison guards and other inmates.","sumSrc":"Oyez","by":{"1":"9"}},{"t":"case","label":"Zablocki v. Redhail","cite":"434 U.S. 374","y":1978,"id":"1977/76-879","sc":1,"sum":"The Court held that Wisconsin's statute violated the Equal Protection Clause and reaffirmed that marriage was a fundamental right. In the majority opinion authored by Justice Thurgood Marshall, the Court emphasized marriage as part of the right to privacy found in the Fourteenth Amendment as identified in Griswold v. Connecticut.","sumSrc":"Oyez","by":{"1":"7"}},{"t":"usc","label":"8 U.S.C. § 1183a","url":"https://www.law.cornell.edu/uscode/text/8/1183a","by":{"1":"5"}},{"t":"law","label":"Pub. L. No. 107-56","url":"https://www.govinfo.gov/link/plaw/107/public/56","by":{"1":"22"}}]};